import torch
from ptx_harness import ptx_load, ptx_launch

# PTX source for a simple fp16 GEMM (C = A @ B) targeting NVIDIA RTX PRO 6000 Blackwell (SM 90)
PTX_SOURCE = r'''
.version 7.8
.target sm_90
.address_size 64

.visible .entry gemm_fp16 (
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    // --------------------------------------------------
    // Load kernel arguments
    // --------------------------------------------------
    .reg .b64 a_ptr, b_ptr, c_ptr;
    .reg .u32 n;
    ld.param.u64 a_ptr, [A_ptr];
    ld.param.u64 b_ptr, [B_ptr];
    ld.param.u64 c_ptr, [C_ptr];
    ld.param.u32 n, [N];

    // --------------------------------------------------
    // Thread / block indices
    // --------------------------------------------------
    .reg .u32 tid_x, tid_y, blk_x, blk_y, ntid_x, ntid_y;
    mov.u32 tid_x, %tid.x;
    mov.u32 tid_y, %tid.y;
    mov.u32 blk_x, %ctaid.x;
    mov.u32 blk_y, %ctaid.y;
    mov.u32 ntid_x, %ntid.x;
    mov.u32 ntid_y, %ntid.y;

    // --------------------------------------------------
    // Compute global row / column indices
    // --------------------------------------------------
    .reg .u32 row, col;
    mad.lo.u32 row, blk_y, ntid_y, tid_y;   // row = blockIdx.y * blockDim.y + threadIdx.y
    mad.lo.u32 col, blk_x, ntid_x, tid_x;   // col = blockIdx.x * blockDim.x + threadIdx.x

    // --------------------------------------------------
    // Bounds check
    // --------------------------------------------------
    .reg .pred p_oob;
    setp.ge.u32 p_oob, row, n;
    @p_oob bra DONE;
    setp.ge.u32 p_oob, col, n;
    @p_oob bra DONE;

    // --------------------------------------------------
    // Accumulator (FP32 for better precision)
    // --------------------------------------------------
    .reg .f32 sum;
    mov.f32 sum, 0.0;

    // --------------------------------------------------
    // Loop over K dimension
    // --------------------------------------------------
    .reg .u32 k;
    mov.u32 k, 0;

K_LOOP:
    setp.ge.u32 p_oob, k, n;
    @p_oob bra K_END;

    // ---- Load A[row, k] (fp16) ----
    .reg .u32 idx_a;
    mad.lo.u32 idx_a, row, n, k;            // row * N + k
    .reg .b64 off_a;
    mul.wide.u32 off_a, idx_a, 2;           // 2 bytes per fp16
    add.u64 off_a, off_a, a_ptr;
    .reg .f16 a_h;
    ld.global.f16 a_h, [off_a];

    // ---- Load B[k, col] (fp16) ----
    .reg .u32 idx_b;
    mad.lo.u32 idx_b, k, n, col;            // k * N + col
    .reg .b64 off_b;
    mul.wide.u32 off_b, idx_b, 2;
    add.u64 off_b, off_b, b_ptr;
    .reg .f16 b_h;
    ld.global.f16 b_h, [off_b];

    // ---- Convert to FP32 ----
    .reg .f32 a_f, b_f;
    cvt.f32.f16 a_f, a_h;
    cvt.f32.f16 b_f, b_h;

    // ---- FMA accumulation ----
    fma.rn.f32 sum, a_f, b_f, sum;

    // ---- Increment k ----
    add.u32 k, k, 1;
    bra.uni K_LOOP;

K_END:
    // --------------------------------------------------
    // Store result (convert back to fp16)
    // --------------------------------------------------
    .reg .f16 c_h;
    cvt.rn.f16.f32 c_h, sum;                // fp32 -> fp16

    .reg .u32 idx_c;
    mad.lo.u32 idx_c, row, n, col;          // row * N + col
    .reg .b64 off_c;
    mul.wide.u32 off_c, idx_c, 2;
    add.u64 off_c, off_c, c_ptr;

    st.global.f16 [off_c], c_h;

DONE:
    ret;
